import json
import re
from collections import deque
from pathlib import Path
from typing import Dict, List, Tuple


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []
    defined_ids = set()

    current_id = None
    current_line: Tuple[str, str, str] | None = None
    current_choices: List[Tuple[str, str]] = []

    def finalize_node() -> None:
        nonlocal current_id, current_line, current_choices
        if current_id is None:
            return

        if current_choices:
            node = {
                "id": current_id,
                "text": "",
                "speaker": "",
                "type": "choice",
            }
            nodes.append(node)
            defined_ids.add(current_id)
            for choice_text, target in current_choices:
                edges.append({"from": current_id, "to": target, "text": choice_text})
        elif current_line:
            speaker, text_part, target = current_line
            node = {
                "id": current_id,
                "text": text_part,
                "speaker": speaker,
                "type": "line",
            }
            nodes.append(node)
            defined_ids.add(current_id)
            if target:
                edges.append({"from": current_id, "to": target, "text": ""})
        else:
            node = {
                "id": current_id,
                "text": "",
                "speaker": "",
                "type": "line",
            }
            nodes.append(node)
            defined_ids.add(current_id)

        current_id = None
        current_line = None
        current_choices = []

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        if line.startswith("[") and line.endswith("]"):
            finalize_node()
            current_id = line[1:-1].strip()
            continue

        if current_id is None:
            continue

        choice_match = re.match(r"^(\d+)\.\s+(.*)$", line)
        if choice_match:
            choice_body = choice_match.group(2).strip()
            if "->" in choice_body:
                choice_text, target = [part.strip() for part in choice_body.rsplit("->", 1)]
            else:
                choice_text, target = choice_body, ""
            current_choices.append((choice_text, target))
            continue

        if ":" in line:
            speaker, rest = line.split(":", 1)
            speaker = speaker.strip()
            rest = rest.strip()
            if "->" in rest:
                text_part, target = [part.strip() for part in rest.rsplit("->", 1)]
            else:
                text_part, target = rest, ""

            if current_line is None:
                current_line = (speaker, text_part, target)
            else:
                # Merge extra lines into the existing line node.
                prev_speaker, prev_text, prev_target = current_line
                if speaker == prev_speaker and not current_choices:
                    merged_text = f"{prev_text} {text_part}".strip()
                    merged_target = prev_target or target
                    current_line = (speaker, merged_text, merged_target)
                else:
                    merged_text = f"{prev_text} {speaker}: {text_part}".strip()
                    merged_target = prev_target or target
                    current_line = (prev_speaker, merged_text, merged_target)
            continue

        # Fallback line without a speaker.
        if current_line is None and not current_choices:
            if "->" in line:
                text_part, target = [part.strip() for part in line.rsplit("->", 1)]
            else:
                text_part, target = line, ""
            current_line = ("", text_part, target)

    finalize_node()

    targets = {edge["to"] for edge in edges if edge["to"]}

    if "End" in targets and "End" not in defined_ids:
        nodes.append({"id": "End", "text": "", "speaker": "", "type": "line"})
        defined_ids.add("End")

    missing = sorted(target for target in targets if target not in defined_ids and target != "End")
    if missing:
        raise ValueError(f"Missing target nodes: {missing}")

    if nodes:
        start_id = nodes[0]["id"]
        adjacency: Dict[str, List[str]] = {}
        for edge in edges:
            adjacency.setdefault(edge["from"], []).append(edge["to"])

        reachable = set()
        queue = deque([start_id])
        while queue:
            node_id = queue.popleft()
            if node_id in reachable:
                continue
            reachable.add(node_id)
            for target in adjacency.get(node_id, []):
                if target and target in defined_ids:
                    queue.append(target)
                elif target == "End":
                    queue.append(target)

        unreachable = sorted(node["id"] for node in nodes if node["id"] not in reachable)
        if unreachable:
            raise ValueError(f"Unreachable nodes: {unreachable}")

    return {"nodes": nodes, "edges": edges}


def _dot_escape(value: str) -> str:
    return value.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n")


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {", "  rankdir=LR;", "  node [fontname=\"Helvetica\"];" ]

    for node in graph["nodes"]:
        node_id = _dot_escape(node["id"])
        if node["type"] == "choice":
            label_parts = [node["id"], "(choice)"]
            shape = "diamond"
        else:
            label_parts = [node["id"]]
            if node["speaker"] or node["text"]:
                if node["speaker"]:
                    label_parts.append(f"{node['speaker']}: {node['text']}")
                else:
                    label_parts.append(node["text"])
            shape = "box"

        label = _dot_escape("\n".join(part for part in label_parts if part))
        lines.append(f"  \"{node_id}\" [label=\"{label}\", shape={shape}];")

    for edge in graph["edges"]:
        from_id = _dot_escape(edge["from"])
        to_id = _dot_escape(edge["to"])
        if edge["text"]:
            label = _dot_escape(edge["text"])
            lines.append(f"  \"{from_id}\" -> \"{to_id}\" [label=\"{label}\"];" )
        else:
            lines.append(f"  \"{from_id}\" -> \"{to_id}\";")

    lines.append("}")
    return "\n".join(lines)


def main() -> None:
    base_dir = Path(__file__).resolve().parent
    script_path = base_dir / "script.txt"
    if not script_path.exists():
        raise FileNotFoundError(f"Script not found at {script_path}")

    graph = parse_script(script_path.read_text(encoding="utf-8"))

    json_path = base_dir / "dialogue.json"
    json_path.write_text(json.dumps(graph, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")

    dot_path = base_dir / "dialogue.dot"
    dot_path.write_text(graph_to_dot(graph) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
